{type==='rsvp'&&<><label>Number attending<input name="count" type="number" min="1" max="20" defaultValue="1" required/></label><label>Event<input name="event" defaultValue={memorial?.location||'Memorial service'}/></label><label className="full">Accessibility, dietary or transport requests<textarea name="requirements" rows={3}/></label></>}
{type==='flower'&&<><label>Delivery date<input name="deliveryDate" type="date" min={new Date().toISOString().slice(0,10)}/></label><label className="full">Memorial / recipient<input name="memorial" defaultValue={memorial?.name||''}/></label></>}
