useEffect(()=>{if(!page.startsWith('memorial/'))return;setSelected(null);setTributes([]);setMemorialError('');const raw=page.slice(9),[id,q]=raw.split('?');const sample=samples.find(s=>s.id===id);if(sample){setSelected(sample);return}fetch('/api/data?memorial='+encodeURIComponent(id)+(q?'&'+q:'')).then(async r=>{const d:any=await r.json();if(!r.ok)throw Error(d.error);setSelected({...d.memorial,shareToken:d.memorial.shareToken||new URLSearchParams(q||'').get('token')});setTributes(d.tributes)}).catch(e=>setMemorialError(e.message))},[page]);
