const listed=publicRecords.filter(r=>r.kind==='memorial');const memorials=listed.length?listed:samples;const items=(kind:string,fallback:any[]=[])=>{const a=publicRecords.filter(r=>r.kind===kind);return a.length?a:fallback};const services=items('service',serviceDefaults),packages=items('package',packageDefaults),guides=items('article',articles);
const contactButton=(label='Speak with us',className='button')=>config.phone?<a className={className} href={'tel:'+config.phone}><Phone size={16}/>{label}</a>:<button className={className} onClick={()=>go('contact')}>{label}<ArrowRight size={17}/></button>;
